import {createRoot} from 'react-dom/client';
import {useState} from 'react';
import {Users,ShoppingBasket} from 'lucide-react';
import {PosDatabase,setSetting} from '@agristore/offline';
import {type Lease} from '@agristore/domain';
import {PurchasingWorkspace} from '../../apps/web/components/purchasing-workspace';
import {SupplierAccounts} from '../../apps/web/components/supplier-accounts';
import {CreditWorkspace} from '../../apps/web/components/credit-workspace';
import {PriceHistory} from '../../apps/web/components/price-history';
import {CreditSaleConfirmation} from '../../apps/web/components/credit-sale-confirmation';
import type {ConfirmedCreditSale} from '../../apps/web/lib/credit-confirmation';
import {CreditCheckout} from '../../apps/web/components/credit-checkout';
import {HeldSaleControl} from '../../apps/web/components/held-sale';
import {useCart} from '../../apps/web/lib/cart';
import {StoreBrand} from '../../apps/web/components/store-brand';
import {removeHeldSale} from '../../apps/web/lib/held-sale';
declare global {interface Window {creditFixtureLease:Lease;creditTestCommand:(action:string,data:Record<string,unknown>)=>Promise<unknown>;creditFixtureDB:PosDatabase;creditFixtureCart:typeof useCart}}
const lease=window.creditFixtureLease,db=new PosDatabase('TEST-credit-ui');window.creditFixtureDB=db;window.creditFixtureCart=useCart;
const id=(n:number)=>'92000000-0000-4000-8000-'+String(n).padStart(12,'0');
await setSetting(db,'lease',lease);
function Fixture(){const [view,setView]=useState('credit'),[busy,setBusy]=useState(false),[revision,setRevision]=useState(0),[feedback,setFeedback]=useState(''),[withoutShift,setWithoutShift]=useState(false);const [pane,setPane]=useState('orders'),[billTarget,setBillTarget]=useState('');const [receipt,setReceipt]=useState<ConfirmedCreditSale>();const cart=useCart();
 const add=()=>{setReceipt(undefined);cart.clear();cart.add({productId:id(301),unitId:id(401),batchId:null,name:'TEST feeds',unitName:'Kilo',quantity:'10',factor:'1',unitPrice:10000,unitCost:5000,priceVersion:1,lineTotal:100000});useCart.setState({credit:{enabled:true,clientId:id(801),term:60,officialReference:'TEST-NEW-BOOK-009',cash:'200'}});};
 return <div className="app-shell reference-ui"><aside className="sidebar"><a className="wordmark" href="#main"><StoreBrand/></a><nav aria-label="Main navigation"><button onClick={()=>{setPane("inspections");setView("receiving");}}>TEST inspect delivery</button><button className="nav-item" onClick={()=>setView("receiving")}>Orders &amp; deliveries</button><button className="nav-item" aria-label="Clients & credit" onClick={()=>setView('credit')}><Users size={19}/>Clients &amp; credit</button><button className="nav-item" aria-label="Supplier accounts" onClick={()=>setView('supplier')}><Users size={19}/>Supplier accounts</button><button className="nav-item" aria-label="Price history" onClick={()=>setView('prices')}>Price history</button><button className="nav-item" aria-label="Checkout" onClick={()=>setView('checkout')}><ShoppingBasket size={19}/>Checkout</button></nav></aside><div className="workspace"><header className="topbar">Magpet · TEST interface with isolated simulated records</header><main id="main" className="main-content"><div className="page-heading"><h1>{view==='credit'?'Clients & credit':view==='supplier'?'Purchasing':'Credit checkout'}</h1><p>TEST only. No hosted business API is connected.</p></div>{feedback&&<p role="status">{feedback}</p>}{view==='prices'?<PriceHistory organizationId={lease.organizationId} branchId={lease.branchId} products={[]} online disabled={busy}/>:view==='receiving'?<PurchasingWorkspace pane={pane} onPaneChange={setPane} db={db} organizationId={lease.organizationId} branchId={lease.branchId} branchName="TEST Magpet" actorId={lease.cashierId} products={[{id:id(301),name:'TEST feeds',sku:'TEST-FEED',category:'Feeds',baseUnit:'kg',minimumStock:'0',tracksExpiry:false,active:true,batches:[],units:[{id:id(401),name:'Kilo',factor:'1',price:10000,cost:5000,priceVersion:1}]}]} suppliers={[{id:id(601),name:'TEST Grower Supply'}]} role="owner" online disabled={busy} revision={revision} execute={async fn=>{setBusy(true);try{await fn();}catch(e){return e as Error;}finally{setBusy(false);}}} onBillSaved={id=>{setBillTarget(id);setView('supplier');}}/>:view==='supplier'?<SupplierAccounts initialBillId={billTarget} db={db} organizationId={lease.organizationId} branchId={lease.branchId} actorId={lease.cashierId} online disabled={busy} execute={async fn=>{setBusy(true);try{await fn();}catch(e){return e as Error;}finally{setBusy(false);}}}/>:view==='credit'?<CreditWorkspace db={db} organizationId={lease.organizationId} branchId={lease.branchId} actorId={lease.cashierId} owner online disabled={busy} lease={lease} revision={revision} execute={async fn=>{setBusy(true);try{await fn();}catch(e){return e as Error;}finally{setBusy(false);}}}/>:<div className="checkout-layout"><section className="catalog"><h2>TEST product catalog</h2><p>TEST feeds · PHP 100 per kilo</p><button className="button" disabled={busy||!!cart.creditAttempt} onClick={add}>Add TEST basket</button><button type="button" onClick={()=>setWithoutShift(v=>!v)}>{withoutShift?'TEST restore checkout shift':'TEST browse clients without shift'}</button><p>{cart.items.length} sale line(s) selected. This fixture uses the real credit checkout panel.</p></section><aside className="receipt-panel"><div className="receipt-heading"><h2>Current credit sale</h2></div><>{receipt&&!cart.items.length?<CreditSaleConfirmation sale={receipt} branchName="TEST Magpet" onNewSale={()=>setReceipt(undefined)} onAccounts={()=>setView('credit')}/>:<CreditCheckout key={withoutShift?"no-shift":"shift"} db={db} organizationId={lease.organizationId} branchId={lease.branchId} lease={withoutShift?undefined:lease} online disabled={busy} onWorking={setBusy} onSaved={async saved=>{if(cart.heldDraftId)await removeHeldSale(db,lease,cart.heldDraftId);cart.clear();setReceipt(saved);setFeedback('Credit sale confirmed once.');setRevision(n=>n+1);}}/>}</><HeldSaleControl db={db} lease={lease} cash="" onCash={()=>{}} disabled={busy} onWorking={setBusy} revision={String(revision)}/></aside></div>}</main></div></div>;
}
createRoot(document.getElementById('root')!).render(<Fixture/>);
